package oathdigital.application

import oathdigital.model._

sealed trait GameCommand extends Product with Serializable
object GameCommand:
  final case class Begin(chronicle: Chronicle, orders: SetupOrders)
      extends GameCommand
  final case class StartWalker(procedure: StartableRef, start: StartPayload)
      extends GameCommand
  final case class ResolveWalker(actor: PlayerId, treeDecision: TreeDecision)
      extends GameCommand
  /** Requests an authoritative app-layer roll for the currently parked pool.
    * Faces are generated by DefenseDicePort and enter the rules layer only
    * after the command has been validated.
    *
    * `actor` is the requester bound by the transport, checked against the
    * durable parked position's own actor by `OathRules.walkerResumeContext`
    * before anything is applied -- see C1: without it any authenticated
    * player in the game could resume another player's parked walker.
    */
  final case class RollWalker(actor: PlayerId, pool: PoolKey) extends GameCommand
  final case class EndWake(playerId: PlayerId) extends GameCommand
  final case class PeekSiteRelics(playerId: PlayerId) extends GameCommand
  final case class RevealOwnedRelic(playerId: PlayerId, relic: RelicId)
      extends GameCommand
  final case class MoveWarbands(playerId: PlayerId, toSite: Boolean, amount: Int)
      extends GameCommand
  final case class BeginRest(playerId: PlayerId) extends GameCommand
  final case class FinishRest(playerId: PlayerId) extends GameCommand
  /** Declines the queued action at the head of the queue (follow-up
    * actions design). */
  final case class SkipFollowUp(playerId: PlayerId) extends GameCommand
  final case class UsePower(playerId: PlayerId, power: PowerId,
      source: DecisionOptionRef) extends GameCommand
  /** Takes back the latest live command batch, which `actor` must have
    * issued (undo design, "Rulings"). */
  final case class Undo(actor: PlayerId) extends GameCommand
  /** Restores the batch most recently taken back since the last command
    * batch, which `actor` must have issued (undo design, "Redo"). */
  final case class Redo(actor: PlayerId) extends GameCommand
  /** A command the service routes to its consent desk, never to the rules'
    * walker gate: each is legal over a parked decision (consent design,
    * "Commands"). */
  sealed trait ConsentCommand extends GameCommand
  /** `granter` sets their standing answer for `requester` on `power`. */
  final case class SetConsentPreference(granter: PlayerId, power: PowerId,
      requester: PlayerId, setting: ConsentSetting) extends ConsentCommand
  /** `requester` asks the rulers of the powers blocking `target` at the
    * parked `decisionId` for consent to choose it. */
  final case class RequestConsent(requester: PlayerId, decisionId: String,
      target: DecisionOptionRef) extends ConsentCommand
  /** `granter` answers the request waiting on them. */
  final case class AnswerConsent(granter: PlayerId, choice: ConsentChoice)
      extends ConsentCommand

  /** The player a command's batch is recorded for, in the `CommandAccepted`
    * that opens it (undo design, "Terms"): its actor. Begin has none, so a
    * journal still begins with `GameStarted`; an Undo or a Redo appends its
    * marker alone. */
  def issuer(command: GameCommand): Option[PlayerId] = command match
    case Begin(_, _) => None
    case StartWalker(_, start) => Some(start.actor)
    case ResolveWalker(actor, _) => Some(actor)
    case RollWalker(actor, _) => Some(actor)
    case EndWake(player) => Some(player)
    case PeekSiteRelics(player) => Some(player)
    case RevealOwnedRelic(player, _) => Some(player)
    case MoveWarbands(player, _, _) => Some(player)
    case BeginRest(player) => Some(player)
    case FinishRest(player) => Some(player)
    case SkipFollowUp(player) => Some(player)
    case UsePower(player, _, _) => Some(player)
    case Undo(_) => None
    case Redo(_) => None
    case _: ConsentCommand => None

/** Generic action-start data: who starts, and what they selected before
  * the action started.
  *
  * `startArgs` (batch-1 Task 5) is that selection, for an action whose tree
  * needs it. They are the same `DecisionOptionRef`s a decision option names,
  * and the command layer does not interpret them: `OathRules.startWalker`
  * hands them to the registered action's own builder, which rejects a shape
  * it did not ask for. A start names no modifiers: the action asks for them
  * inside the walk (modifier walker design).
  */
final case class StartPayload(actor: PlayerId,
    startArgs: Vector[DecisionOptionRef] = Vector.empty)

/** One answer to the currently parked generic walker decision. */
final case class TreeDecision(decisionId: String, answer: DecisionAnswer)
